async function bootstrapRefresh(){const r=await rpc('bootstrap');if(r.ok){state.data=r.data;state.players=r.data.players||state.players;state.summary=r.data.summary||state.summary;$('#framework').textContent=(r.data.framework||'standalone').toUpperCase();render();await loadPage()}}
function openPalette(){const rows=getPageDefs().filter(x=>x[2]).map(([id,key])=>({label:t(key),page:id}));state.paletteRows=rows;$('#paletteResults').innerHTML=rows.map((r,i)=>`<div class="palette-result" data-palette="${i}"><b>${esc(r.label)}</b><span class="muted">PAGE</span></div>`).join('');$('#palette').classList.remove('hidden');setTimeout(()=>$('#paletteInput')?.focus(),0)}
function closePalette(){$('#palette').classList.add('hidden');$('#paletteInput').value=''}
function runQuick(k){closeQuick();if(k==='players')return enterPage('players');if(k==='reports'){state.page='moderation';state.sub='reports';render();return loadReports(1)}if(k==='staffChat'){state.page='staff';state.sub='chat';render();return loadChannelChat()}if(k==='world'){state.page='world';state.sub='control';render();return loadWorld()}if(k==='logs')return enterPage('logs');if(k==='vehicleSpawn'){state.page='vehicles';state.sub='catalog';render();return loadVehicles(1)}if(k==='gotoWaypoint')return localAction('teleportWaypoint');if(k==='noclip')return localAction('toggleNoclip');if(k==='heal')return localAction('healSelf');if(k==='vehicleRepair')return localAction('vehicleRepair');toast(`Quick action ${k} requires a selected player/context.`,'error')}
function bind(){document.addEventListener('click',e=>{const p=e.target.closest('button[data-page]');if(p){enterPage(p.dataset.page);return}const s=e.target.closest('button[data-sub]');if(s){enterSub(s.dataset.sub);return}const q=e.target.closest('[data-quick]');if(q){runQuick(q.dataset.quick);return}const a=e.target.closest('[data-action]');if(a){action(a.dataset.action,a);return}const pr=e.target.closest('[data-palette]');if(pr){const row=state.paletteRows[Number(pr.dataset.palette)];if(row){closePalette();enterPage(row.page)}}});
 document.addEventListener('dragstart',e=>{const row=e.target.closest('.widget-config');if(!row)return;state.dragWidget=row;row.classList.add('dragging');if(e.dataTransfer)e.dataTransfer.effectAllowed='move'});document.addEventListener('dragover',e=>{const row=e.target.closest('.widget-config');if(!row||!state.dragWidget||row===state.dragWidget)return;e.preventDefault();const box=row.getBoundingClientRect();row.parentElement.insertBefore(state.dragWidget,e.clientY<box.top+box.height/2?row:row.nextSibling);$$('.widget-config').forEach((x,i)=>{const inp=$('.widgetOrder',x);if(inp)inp.value=i+1})});document.addEventListener('dragend',()=>{if(state.dragWidget)state.dragWidget.classList.remove('dragging');state.dragWidget=null});
 content.addEventListener('input',e=>{if(e.target.id==='playerSearch'){state.filter=e.target.value;clearTimeout(state.playerSearchTimer);state.playerSearchTimer=setTimeout(()=>{if(state.page==='players'){if(state.filter.trim())searchPlayers(state.filter);else refreshPlayers()}},350)}if(e.target.type==='range'){const o=e.target.nextElementSibling;if(o&&o.tagName==='OUTPUT')o.value=Number(e.target.value).toFixed(Number(e.target.step)<1?2:0);if(e.target.id==='motionSpeed'){state.theme.motionSpeed=Number(e.target.value||1);saveTheme()}}});
 subnav.addEventListener('change',e=>{if(e.target.id==='sectionSelect')enterSub(e.target.value)});
 content.addEventListener('change',async e=>{if(e.target.id==='rankMode'){const mode=e.target.value;if(mode==='live'){await refreshPlayers()}else{const r=await rpc('players:ranked',{mode});if(r.ok){state.players=r.data||[];render()}}return}if(e.target.classList.contains('modInput')){const slot=Number(e.target.dataset.slot),count=Number(e.target.dataset.count),idx=Math.max(-1,Math.min(count-1,Number(e.target.value)||-1));e.target.value=idx;await localAction('vehicleMod',{slot,index:idx})}});
 content.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement))return;const local=img.dataset.local,fb=img.dataset.fallback;if(local){delete img.dataset.local;img.src=local;return}if(fb){delete img.dataset.fallback;img.src=fb}},true);
 $('#brandHome').onclick=()=>enterPage('dashboard');$('#dockBtn').onclick=()=>post('dock');$('#dockExpand').onclick=()=>post('expand');$('#refreshBtn').onclick=bootstrapRefresh;$('#searchBtn').onclick=openPalette;$('#settingsBtn').onclick=()=>enterPage('settings');$('#closeBtn').onclick=()=>post('close');$('#modalClose').onclick=closeModal;$('#dutyBtn').onclick=()=>action('toggleDuty',$('#dutyBtn'));$('#quickBtn').onclick=openQuick;$('#quickClose').onclick=closeQuick;
 $('#paletteInput').addEventListener('input',e=>{const q=e.target.value.toLowerCase();const rows=getPageDefs().filter(x=>x[2]&&t(x[1]).toLowerCase().includes(q)).map(([id,key])=>({label:t(key),page:id}));state.paletteRows=rows;$('#paletteResults').innerHTML=rows.map((r,i)=>`<div class="palette-result" data-palette="${i}"><b>${esc(r.label)}</b><span class="muted">PAGE</span></div>`).join('')});
 $('#operatorDock').addEventListener('click',e=>{const b=e.target.closest('[data-dock-action]');if(b)runQuick(b.dataset.dockAction)});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#quickWheel').classList.contains('hidden'))closeQuick();else if(!$('#palette').classList.contains('hidden'))closePalette();else if(!$('#modal').classList.contains('hidden'))closeModal();else post('close')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}})
}
function updateDock(){const s=state.summary||state.data?.summary||{};$('#dockPlayers').textContent=s.onlinePlayers??state.players.length??0;$('#dockReports').textContent=s.openReports??0;$('#dockStaff').textContent=s.onlineStaff??0}
function applyUiMode(mode){
 mode=(mode==='FULL'||mode==='DOCKED')?mode:'HIDDEN';
 app.dataset.uiMode=mode;state.open=mode==='FULL';
 app.classList.toggle('hidden',mode==='HIDDEN');
 app.setAttribute('aria-hidden',mode==='HIDDEN'?'true':'false');
 $('#operatorDock').classList.toggle('hidden',mode!=='DOCKED');
 $('.shell').classList.toggle('dock-shell-hidden',mode==='DOCKED');updateDock()
}
window.addEventListener('message',async e=>{
 const m=e.data||{};
 if(m.type==='nuiProbe') {
  const css=el=>getComputedStyle(el);
  post('nuiSurfaceStatus',{version:'0.14.2',href:location.href,preview:PREVIEW,uiMode:app.dataset.uiMode||'HIDDEN',rootClass:app.className,rootDisplay:css(app).display,rootVisibility:css(app).visibility,htmlBg:css(document.documentElement).backgroundColor,bodyBg:css(document.body).backgroundColor}).catch(()=>{});
 }
 else if(m.type==='visible'){applyUiMode(m.show?'FULL':'HIDDEN')}
 else if(m.type==='uiMode'){applyUiMode(m.mode)}
 else if(m.type==='dockInteract'){$('#operatorDock').classList.toggle('interactive',m.active===true)}
 else if(m.type==='bootstrap'){state.data=m.data;state.players=m.data.players||[];state.summary=m.data.summary||null;state.widgets=m.data.widgets?.default||[];state.language=localStorage.getItem('rsadmin.lang')||m.data.language||'en';await loadLocale(state.language);loadTheme();$('#framework').textContent=(m.data.framework||'standalone').toUpperCase();/* Data bootstrap is NOT permission to open the NUI. Only uiMode:FULL
  can display it; a delayed bootstrap must never reopen a closed menu. */render();await Promise.all([loadPage(),loadDuty(),loadQuickPrefs()]);if(can('world')){const w=await rpc('world:state');if(w.ok)state.world=w.data}}
 else if(m.type==='staffChat'){state.chat.push(m.data);if(state.chat.length>100)state.chat.shift();if(state.page==='staff'&&state.sub==='chat'&&state.chatChannel==='staff')await loadChannelChat();else if(state.settings.staffChatNotifications!==false)toast(`STAFF · ${m.data?.name||'Staff'}`)}
 else if(m.type==='staffChatChannel'){if(m.data?.channel===state.chatChannel){state.channelChat.push(m.data);if(state.channelChat.length>120)state.channelChat.shift();if(state.page==='staff'&&state.sub==='chat'){render();setTimeout(()=>{const c=$('#chatList');if(c)c.scrollTop=c.scrollHeight},0)}}else if(state.settings.staffChatNotifications!==false)toast(`#${m.data?.channel||'staff'} · ${m.data?.name||'Staff'}`)}
 else if(m.type==='dutyState'){state.duty=m.data||{on:false};updateDutyButton();if(state.page==='staff'&&state.sub==='duty')render()}
 else if(m.type==='quickOpen'){if(!state.quickPrefs)await loadQuickPrefs();openQuick()}
 else if(m.type==='worldState'){state.world=m.data;if(state.page==='world'&&state.sub==='control')render()}
 else if(m.type==='reportAlert'){if(state.settings.reportNotifications!==false)toast(`New report #${m.data?.id||''}`);if(state.page==='moderation'&&state.sub==='reports')await loadReports(state.reportList.page||1)}
});
setInterval(()=>{if(state.open&&state.page==='players'&&state.sub!=='pathways'){if(state.filter.trim())searchPlayers(state.filter);else refreshPlayers();if(state.mapEntityMode==='vehicles')loadMapVehicles()}},2000);

