const MOCKITEM=['radio','lockpick','repairkit','bandage','water','sandwich'].map(name=>({name,label:name.toUpperCase(),weight:100,image:''}));
async function mock(endpoint,p){
  if(endpoint==='close'){applyUiMode('HIDDEN');return {ok:true};} if(endpoint==='dock'){applyUiMode('DOCKED');return {ok:true};} if(endpoint==='expand'){applyUiMode('FULL');return {ok:true};}
  if(endpoint==='localAction'){
    if(p.action==='vehicleCatalogue'){
      const q=(p.data.q||'').toLowerCase();
      const rows=MOCKVEH.filter(v=>!q||v.model.includes(q)||v.label.toLowerCase().includes(q));
      return {ok:true,data:{rows,total:rows.length,page:1,pages:1,pageSize:24}};
    }
    if(['vehicleInspect','vehicleMaxAll','vehicleRandom'].includes(p.action)){
      return {ok:true,data:{model:'sultanrs',displayName:'Karin Sultan RS',slots:[{slot:0,label:'Spoiler',count:8,current:2,currentName:'Street Wing'},{slot:11,label:'Engine',count:4,current:3,currentName:'EMS 4'}],extras:[]}};
    }
    if(p.action==='vehicleConfiguredProps')return {ok:true,data:{model:0,color1:0,color2:0,plate:'RSADMIN'}};
    return {ok:true};
  }
  if(endpoint==='rpc'){
    const n=p.name,d=p.data||{};
    if(n==='bootstrap')return {ok:true,data:MOCK};
    if(n==='dashboard:summary'||n==='economy:summary')return {ok:true,data:{onlinePlayers:4,openReports:1,activeBans:0,activeJails:1,cash:42500,bank:942000,totalEconomy:984500,richest:[{name:'RS Owner',wealth:450000,playtime:{currentSeconds:18900,totalSeconds:240000}},{name:'Steve',wealth:260000,playtime:{currentSeconds:7200,totalSeconds:76000}}],highValue:[{amount:125000,account:'bank',kind:'player_transfer'}],recentActions:[{action:'jail',staff:'RS Owner'}]}};
    if(n==='players:refresh')return {ok:true,data:MOCK.players};
    if(n==='player:profile'){
      const x=MOCK.players.find(x=>x.id===Number(d.target))||MOCK.players[0];
      return {ok:true,data:{...x,citizenid:'CID001',cash:5000,bank:450000,job:{label:'Police'},gang:{label:'None'},identifiers:['license:example','discord:123'],playtime:{totalSeconds:240000,currentSeconds:18900,sessions:44},currentVehicle:{plate:'RSADMIN'}}};
    }
    if(n==='player:inventory')return {ok:true,data:MOCKITEM.map((x,i)=>({...x,count:i+1,slot:i+1}))};
    if(n==='player:vehicles')return {ok:true,data:[{modelName:'sultanrs',garage:'pillboxgarage',props:{plate:'RS001'}},{modelName:'buffalo4',garage:'pillboxgarage',props:{plate:'RS002'}}]};
    if(n==='player:history')return {ok:true,data:[{action:'heal',at:Date.now()/1000},{action:'give vehicle',at:Date.now()/1000-200}]};
    if(n==='catalog:items')return {ok:true,data:{rows:MOCKITEM,total:MOCKITEM.length,page:1,pages:1,pageSize:24}};
    if(n==='widgets:get'||n==='widgets:save')return {ok:true,data:d.widgets||MOCK.widgets.default};
    if(n==='world:state'||n==='world:patch')return {ok:true,data:{weather:d.weather||'CLEAR',hour:d.hour??12,minute:d.minute??0,blackout:d.blackout||false,rain:d.rain||0,wind:d.wind||0,windDirection:d.windDirection||0,traffic:d.traffic??1,parked:d.parked??1,randomVehicles:d.randomVehicles??1,peds:d.peds??1,scenarios:d.scenarios??1}};
    if(n==='builder:list')return {ok:true,data:[]};
    if(n==='jail:list'||n==='jail:history')return {ok:true,data:[]};
    if(n==='ban:history')return {ok:true,data:[]};
    if(n==='staffchat:list')return {ok:true,data:[]};
    if(n==='staff:list')return {ok:true,data:[]};
    if(n==='economy:transactions')return {ok:true,data:{rows:[],page:1,pages:1,total:0}};
    if(n==='jobs:list')return {ok:true,data:[{name:'police',label:'Police'},{name:'mechanic',label:'Mechanic'}]};
    if(n==='gangs:list')return {ok:true,data:[{name:'none',label:'None'},{name:'ballas',label:'Ballas'}]};
    if(n==='players:ranked')return {ok:true,data:MOCK.players.map((x,i)=>({...x,wealth:500000-i*100000,bank:450000-i*80000,cash:50000,vehicleCount:4-i,playtime:{totalSeconds:240000-i*30000}}))};
    if(n==='players:search')return {ok:true,data:MOCK.players.filter(x=>`${x.id} ${x.name}`.toLowerCase().includes(String(d.q||'').toLowerCase()))};
    if(n==='warning:list')return {ok:true,data:[{id:1,name:'Steve',reason:'Fail RP',at:Date.now()/1000-900}]};
    if(n==='communityService:list')return {ok:true,data:[{id:1,name:'Rob',reason:'Staff punishment',count:20,remaining:7,identifier:'license:mock'}]};
    if(n==='watchlist:list')return {ok:true,data:[{id:1,name:'Lasie',note:'Monitor high-value transfers'}]};
    if(n==='staffNote:list')return {ok:true,data:[{id:1,name:'Steve',note:'Follow-up required',staff:'RS Owner'}]};
    if(n==='staffGroup:list')return {ok:true,data:[{key:'owner',label:'Owner',rank:100,color:'#ff3f8f',position:'Server Owner',builtin:true},{key:'admin',label:'Admin',rank:80,color:'#268cff',position:'Administration',builtin:true},{key:'moderator',label:'Moderator',rank:50,color:'#20d4e8',position:'Moderation',builtin:true},{key:'senior_admin',label:'Senior Admin',rank:90,color:'#9a5dff',position:'Senior Administration',builtin:false}]};
    if(n==='logs:list')return {ok:true,data:{rows:[{at:Date.now()/1000,category:'moderation',action:'jail',staff:'RS Owner',target:'Steve',detail:'10 min | Fail RP'},{at:Date.now()/1000-220,category:'economy',action:'economy transfer',staff:'RS Owner',target:'Rob',detail:'$125,000 bank'}],page:1,pages:1,total:2,pageSize:50}};
    if(n==='report:list')return {ok:true,data:{rows:MOCK.reports,total:MOCK.reports.length,page:1,pages:1,pageSize:30}};
    if(n==='staff:dutyState')return {ok:true,data:{on:true,since:Date.now()/1000-3600,role:'owner'}};
    if(n==='staff:dutyLogs')return {ok:true,data:{rows:[{at:Date.now()/1000-3600,action:'on',name:'RS Owner',role:'owner'},{at:Date.now()/1000-7200,action:'off',name:'Example Admin',role:'admin',seconds:3600}],total:2,page:1,pages:1}};
    if(n==='staffchat:channels')return {ok:true,data:[{key:'staff',label:'Staff',color:'#20a9ff'},{key:'management',label:'Management',color:'#ff3f8f'}]};
    if(n==='staffchat:channelHistory')return {ok:true,data:[{at:Date.now()/1000-90,channel:d.channel||'staff',name:'RS Owner',role:'owner',color:'#ff3f8f',message:'Checking the live operations queue.'}]};
    if(n==='map:vehicles')return {ok:true,data:[{netId:10,model:123,plate:'RS001',x:225,y:-805,z:30,driver:'Steve',owner:'Steve',occupied:true},{netId:11,model:456,plate:'PD042',x:415,y:-980,z:30,driver:null,owner:'Rob',occupied:false}]};
    if(n==='resource:list')return {ok:true,data:[{name:'qbx_core',state:'started',protected:true},{name:'ox_inventory',state:'started',protected:true},{name:'rs-phone',state:'started',protected:false},{name:'rs-hvac',state:'stopped',protected:false}]};
    if(n==='bridge:status')return {ok:true,data:{framework:{provider:'qbox',state:'started'},inventory:{provider:'ox_inventory',state:'started'},housing:{provider:'qbx_properties',state:'started'},target:{provider:'ox_target',state:'started'},clothing:{provider:'illenium-appearance',state:'started'},screenshots:{provider:'screenshot-basic',state:'started'},sounds:{provider:'interact-sound',state:'started'},vehicleKeys:{provider:'qbx_vehiclekeys',state:'started'}}};
    if(n==='quickmenu:get'||n==='quickmenu:save')return {ok:true,data:{mode:d.mode||'radial',actions:d.actions||['players','gotoWaypoint','noclip','heal','reports','staffChat','vehicleRepair','world'],settings:d.settings||{staffChatNotifications:true,reportNotifications:true,disasterNotifications:true}}};if(n==='vehicle:cleanupScheduledList')return {ok:true,data:[]};if(n==='maintenance:state')return {ok:true,data:{active:false}};if(n==='vehicle:ownerSearch')return {ok:true,data:{rows:[{plate:'RS001',modelName:'sultanrs',ownerName:'Example Player',citizenid:'ABC123',garage:'pillboxgarage'}],total:1,page:1,pages:1,pageSize:30}};
    if(n==='server:time')return {ok:true,data:{unix:Date.now()/1000,utc:new Date().toUTCString(),localTime:new Date().toLocaleString()}};
    if(n==='player:properties')return {ok:true,data:[{id:'prop-1',label:'Vespucci Apartment',address:'Vespucci Blvd'}]};
    return {ok:true,data:true};
  }
  return {ok:true};
}

