  const position=(x,y)=>({left:Math.max(0,Math.min(100,(Number(x)+4000)/8500*100)),top:Math.max(0,Math.min(100,(1-(Number(y)+4400)/12400)*100))});
  const mapSurface=markers=>`<div class="map-viewport ${state.mapMode}"><div class="map-stage"><div class="tactical-map map-geographic">${markers}<div class="map-grid-label">SAN ANDREAS</div></div></div><div class="map-caption">Live positions · click a marker to inspect · routing buckets are shown in player profiles.</div></div>`;
  const mapSwitch=()=>`<div class="vehicle-map-row">${btn('PLAYERS','mapPlayers',state.mapEntityMode==='players'?'accent':'')}${btn('VEHICLES','mapVehicles',state.mapEntityMode==='vehicles'?'accent':'')}</div>`;
  mapHtml=ps=>state.mapEntityMode==='vehicles'?vehicleMapHtml(state.mapVehicles):mapSwitch()+mapSurface(ps.map(p=>{const pos=position(p.x,p.y);return `<button class="marker ${p.id===state.selectedPlayer?'selected':''}" data-studio="selectPlayer" data-id="${p.id}" style="left:${pos.left}%;top:${pos.top}%" aria-label="Select ${esc(p.name)}"></button><button class="marker-label" data-studio="selectPlayer" data-id="${p.id}" style="left:${pos.left}%;top:${pos.top}%">#${p.id} ${esc(p.name)}</button>`}).join(''));
  vehicleMapHtml=rows=>mapSwitch()+mapSurface((rows||[]).map(v=>{const pos=position(v.x,v.y);return `<button class="vehicle-marker ${v.occupied?'occupied':''}" data-action="worldVehicle" data-netid="${v.netId}" style="left:${pos.left}%;top:${pos.top}%" title="${esc(v.plate||'NO PLATE')}"></button><button class="vehicle-marker-label" data-action="worldVehicle" data-netid="${v.netId}" style="left:${pos.left}%;top:${pos.top}%">${esc(v.plate||'NO PLATE')}</button>`}).join(''));
  const categories = ['Compacts','Sedans','SUVs','Coupes','Muscle','Sports classics','Sports','Super','Motorcycles','Off-road','Industrial','Utility','Vans','Cycles','Boats','Helicopters','Planes','Service','Emergency','Military','Commercial','Trains','Open wheel'];
