    palettes.innerHTML=Object.entries(PALETTES).map(([key,colors],i)=>`<button class="palette-card ${state.theme?.palette===key?'selected':''}" data-action="themePalette" data-value="${key}"><div class="palette-scene" style="background-image:linear-gradient(0deg,${colors[0]}55,transparent),url('assets/wallpapers/${WALLS[[0,4,5,12,8,1,6,7][i]]}')"></div><div class="palette-colors">${[colors[0],colors[1],'#172332','#dce6ef'].map(color=>`<i style="background:${color}"></i>`).join('')}</div><b>${esc(key.toUpperCase())}</b></button>`).join('');
