  enterSub=async sub=>{document.activeElement?.blur();content.scrollTop=0;state.assetFilter='all';await originalEnterSub(sub);};
  async function workspace(page,sub){await enterPage(page);if(sub&&state.sub!==sub)await enterSub(sub);}
  async function copyText(value){
    if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(value);toast('Copied');return;}catch(_){}}
    openModal('COPY VALUE',`<label class="field">Select and copy<input class="input" value="${esc(value)}" readonly></label>`);
  }
  const originalAction=action;
